package com.example.blades360;
import android.app.Activity;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.zip.GZIPInputStream;

final class IptvClient {
 static final int PLAYLIST_FILE=3820,GUIDE_FILE=3821;
 final MainActivity a;final String storage;final android.content.SharedPreferences prefs;final ExecutorService worker=Executors.newSingleThreadExecutor();
 JSONObject config=new JSONObject();ArrayList<IptvData.Channel> channels=new ArrayList<>();ArrayList<IptvData.Programme> programmes=new ArrayList<>();
 volatile int generation;boolean closed,busy;String status="Add your M3U playlist in X Settings";Runnable changed=()->{};
 final android.util.LruCache<String,Bitmap> images=new android.util.LruCache<String,Bitmap>(12*1024*1024){protected int sizeOf(String k,Bitmap b){return b.getByteCount();}};final Set<String> pending=new HashSet<>();
 final Map<String,ArrayList<IptvData.Programme>> guideIndex=new HashMap<>();
 void indexGuide(){guideIndex.clear();for(IptvData.Programme p:programmes)guideIndex.computeIfAbsent(p.channel,k->new ArrayList<>()).add(p);}
 IptvClient(MainActivity a){this(a,"iptv");}
 IptvClient(MainActivity a,String storage){this.a=a;this.storage=storage;prefs=a.getSharedPreferences(storage+"_options",0);worker.execute(()->{JSONObject saved=new JSONObject();ArrayList<IptvData.Channel> list=new ArrayList<>();ArrayList<IptvData.Programme> guide=new ArrayList<>();try{saved=new JSONObject(PrivateMediaFile.read(a,storage+"-config.bin"));JSONObject cache=new JSONObject(PrivateMediaFile.read(a,storage+"-cache.bin"));if(cache.optString("source").equals(saved.optString("playlist"))){JSONArray rows=cache.getJSONArray("channels");for(int i=0;i<rows.length();i++)list.add(IptvData.Channel.from(rows.getJSONObject(i)));}try{JSONObject epg=new JSONObject(PrivateMediaFile.read(a,storage+"-guide.bin"));if(epg.optString("source").equals(saved.optString("guide"))){JSONArray rows=epg.getJSONArray("programmes");for(int i=0;i<rows.length();i++)guide.add(IptvData.Programme.from(rows.getJSONObject(i)));}}catch(Exception ignored){}}catch(Exception ignored){}JSONObject restored=saved;a.runOnUiThread(()->{if(closed||generation!=0)return;config=restored;channels=list;programmes=guide;indexGuide();if(!channels.isEmpty())status=channels.size()+" saved channels · Y refresh";notifyChanged();});});}
 void notifyChanged(){if(!closed)changed.run();}
 String source(){return config.optString("playlist");}String guideSource(){return config.optString("guide");}
 void set(String key,String value){value=value.trim();if(!value.startsWith("content:")&&IptvData.resolve(value,value).isEmpty()){status="Enter a complete HTTP or HTTPS source URL";notifyChanged();return;}try{config.put(key,value);}catch(Exception ignored){}generation++;busy=false;String snapshot=config.toString();worker.execute(()->{try{PrivateMediaFile.write(a,storage+"-config.bin",snapshot);}catch(Exception e){a.runOnUiThread(()->{status="Could not save source securely";notifyChanged();});}});if(key.equals("playlist"))refresh();else refreshGuide();}
 byte[] read(String source,int limit)throws Exception{byte[] data;if(source.startsWith("content:")){try(InputStream in=a.getContentResolver().openInputStream(Uri.parse(source));ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)throw new IOException();byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new IOException();out.write(b,0,n);}data=out.toByteArray();}}else data=MediaHttp.get(source,Collections.singletonMap("User-Agent","Blades360/1.0"),limit);if(data.length>2&&(data[0]&255)==31&&(data[1]&255)==139){try(GZIPInputStream in=new GZIPInputStream(new ByteArrayInputStream(data));ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new IOException();out.write(b,0,n);}data=out.toByteArray();}}return data;}
 void refresh(){if(busy||closed)return;if(source().isEmpty()){status="Add your M3U URL or import a playlist file";notifyChanged();return;}int ticket=++generation;String source=source();busy=true;status="Loading playlist…";notifyChanged();worker.execute(()->{try{IptvData.Playlist parsed=IptvData.playlist(new String(read(source,8*1024*1024),"UTF-8"),source);JSONArray rows=new JSONArray();for(IptvData.Channel c:parsed.channels)rows.put(c.json());if(ticket!=generation)return;PrivateMediaFile.write(a,storage+"-cache.bin",new JSONObject().put("source",source).put("channels",rows).toString());a.runOnUiThread(()->{if(closed||ticket!=generation)return;channels=parsed.channels;busy=false;pending.clear();status=channels.size()+" channels loaded";notifyChanged();if(guideSource().isEmpty()&&!parsed.guide.isEmpty())set("guide",parsed.guide);else if(!guideSource().isEmpty())refreshGuide();});}catch(Exception e){a.runOnUiThread(()->{if(closed||ticket!=generation)return;busy=false;status="Could not load playlist. Check source and network; saved channels retained.";notifyChanged();});}});}
 void refreshGuide(){if(closed||busy)return;if(guideSource().isEmpty()){status="Add an XMLTV guide URL or file";notifyChanged();return;}String source=guideSource();Set<String> ids=new HashSet<>();for(IptvData.Channel c:channels)ids.add(c.tvg);int ticket=++generation;busy=true;status="Loading XMLTV guide…";notifyChanged();worker.execute(()->{try{byte[] data=read(source,32*1024*1024);String prefix=new String(data,0,Math.min(data.length,8192),"UTF-8");if(prefix.contains("<!DOCTYPE")||prefix.contains("<!ENTITY"))throw new IOException();ArrayList<IptvData.Programme> list=IptvData.guide(new ByteArrayInputStream(data),ids,System.currentTimeMillis());JSONArray rows=new JSONArray();for(IptvData.Programme p:list)rows.put(p.json());if(ticket!=generation)return;PrivateMediaFile.write(a,storage+"-guide.bin",new JSONObject().put("source",source).put("programmes",rows).toString());a.runOnUiThread(()->{if(closed||ticket!=generation)return;programmes=list;indexGuide();busy=false;status=channels.size()+" channels · "+list.size()+" guide entries";notifyChanged();});}catch(Exception e){a.runOnUiThread(()->{if(closed||ticket!=generation)return;busy=false;status="Could not update XMLTV. Saved guide retained.";notifyChanged();});}});}
 ArrayList<IptvData.Programme> guide(IptvData.Channel c){return new ArrayList<>(guideIndex.getOrDefault(c.tvg,new ArrayList<>()));}
 IptvData.Programme now(IptvData.Channel c){long now=System.currentTimeMillis();for(IptvData.Programme p:guideIndex.getOrDefault(c.tvg,new ArrayList<>()))if(p.start<=now&&p.end>now)return p;return null;}
 boolean favorite(IptvData.Channel c){return prefs.getStringSet("favorites",Collections.emptySet()).contains(c.id);}
 void favoriteToggle(IptvData.Channel c){Set<String> ids=new HashSet<>(prefs.getStringSet("favorites",Collections.emptySet()));if(!ids.remove(c.id))ids.add(c.id);prefs.edit().putStringSet("favorites",ids).apply();notifyChanged();}
 void recent(IptvData.Channel c){try{JSONArray old=new JSONArray(prefs.getString("recent","[]")),list=new JSONArray().put(c.id);for(int i=0;i<old.length()&&list.length()<50;i++)if(!old.optString(i).equals(c.id))list.put(old.optString(i));prefs.edit().putString("recent",list.toString()).apply();}catch(Exception ignored){}}
 void choose(boolean guide){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);a.startActivityForResult(i,guide?GUIDE_FILE:PLAYLIST_FILE);}
 boolean result(int request,int result,Intent data){if(request!=PLAYLIST_FILE&&request!=GUIDE_FILE)return false;if(result==Activity.RESULT_OK&&data!=null&&data.getData()!=null){try{a.getContentResolver().takePersistableUriPermission(data.getData(),Intent.FLAG_GRANT_READ_URI_PERMISSION);set(request==PLAYLIST_FILE?"playlist":"guide",data.getData().toString());}catch(Exception e){status="Could not open selected file";notifyChanged();}}if(a.iptvBrowser!=null)a.iptvBrowser.requestFocus();return true;}
 Bitmap image(String path){if(path==null||path.isEmpty()||closed)return null;Bitmap b=images.get(path);if(b!=null||pending.contains(path))return b;pending.add(path);worker.execute(()->{Bitmap image=null;try{byte[] bytes=MediaHttp.get(path,Collections.emptyMap(),3*1024*1024);BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);o.inSampleSize=1;while(Math.max(o.outWidth,o.outHeight)/o.inSampleSize>384)o.inSampleSize*=2;o.inJustDecodeBounds=false;image=BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);}catch(Exception ignored){}Bitmap loaded=image;a.runOnUiThread(()->{if(closed)return;if(loaded!=null)images.put(path,loaded);notifyChanged();});});return null;}
 boolean visible(IptvData.Channel c){Set<String> hidden=prefs.getStringSet("hidden_labels",Collections.emptySet());for(String tag:IptvLabels.tags(c))if(hidden.contains(tag))return false;return true;}
 ArrayList<IptvData.Channel> visibleChannels(){ArrayList<IptvData.Channel> out=new ArrayList<>();for(IptvData.Channel c:channels)if(visible(c))out.add(c);return out;}
 TreeMap<String,Integer> labelCounts(){TreeMap<String,Integer> counts=new TreeMap<>();for(IptvData.Channel c:channels)for(String tag:IptvLabels.tags(c))counts.put(tag,counts.getOrDefault(tag,0)+1);return counts;}
 void toggleLabel(String tag){Set<String> hidden=new HashSet<>(prefs.getStringSet("hidden_labels",Collections.emptySet()));if(!hidden.remove(tag))hidden.add(tag);prefs.edit().putStringSet("hidden_labels",hidden).apply();notifyChanged();}
 void showAllLabels(){prefs.edit().remove("hidden_labels").apply();notifyChanged();}
 void close(){closed=true;generation++;worker.shutdownNow();images.evictAll();}
}
